// Generates a year of mock contribution dates and commit levels
function generateMockContributions() {
  const contributions = {};
  const today = new Date();
  const oneYearAgo = new Date();
  oneYearAgo.setFullYear(today.getFullYear() - 1);

  let current = new Date(oneYearAgo);
  while (current <= today) {
    const dateString = current.toISOString().split('T')[0];
    // Generate random levels: 0 (none) to 4 (high) with high probability of 0, 1, 2
    const rand = Math.random();
    let level = 0;
    if (rand > 0.85) level = 4;
    else if (rand > 0.7) level = 3;
    else if (rand > 0.5) level = 2;
    else if (rand > 0.3) level = 1;

    contributions[dateString] = {
      count: level * Math.floor(Math.random() * 3 + 1),
      level: level
    };
    current.setDate(current.getDate() + 1);
  }
  return contributions;
}

